-- Payment Record without billing or computation.
-- The system only RECORDS and VERIFIES payments made outside it. Each applicant has a list of
-- required payments (names only, no amounts); the stage is complete when every one is Verified.
-- Additive only: no column is dropped and no data is deleted.

-- 1. The required payments of an applicant (set by Admin). Removing one is a soft delete.
create table if not exists public."applicant_required_payments" (
  "id" bigint generated by default as identity primary key,
  "applicant_id" bigint not null references public."applicants" ("id") on delete cascade,
  "name" text not null check (btrim("name") <> '' and length("name") <= 80),
  "position" integer not null default 0,
  "created_by_user_id" bigint references public."users" ("id") on delete set null,
  "removed_at" timestamptz,
  "removed_by_user_id" bigint references public."users" ("id") on delete set null,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now()
);
alter table public."applicant_required_payments" enable row level security;
revoke all on public."applicant_required_payments" from anon, authenticated;
create trigger set_updated_at before update on public."applicant_required_payments" for each row execute function public.set_updated_at();
create index if not exists "applicant_required_payments_applicant_idx" on public."applicant_required_payments" ("applicant_id");
create unique index if not exists "applicant_required_payments_name_unique"
  on public."applicant_required_payments" ("applicant_id", lower(btrim("name"))) where "removed_at" is null;

-- 2. The payment plan preset and the "Package or basis" note (plain text, never a number).
alter table public."applicant_payment_plans" add column if not exists "payment_plan_preset" text;
alter table public."applicant_payment_plans" add column if not exists "basis_note" text;
alter table public."applicant_payment_plans" add column if not exists "required_set_at" timestamptz;
alter table public."applicant_payment_plans" add column if not exists "required_set_by_user_id" bigint references public."users" ("id") on delete set null;
comment on column public."applicant_payment_plans"."basis_note" is
  'Reference note for Sales and Admin (e.g. "Package B, per signed LOI"). Plain text: never parsed as a number, added, compared or reported.';

-- 3. Each payment entry records one required payment. One live entry (For verification or
--    Verified) per required payment; rejected entries stay as history. "revision" lets Admin's
--    verify/reject refuse an entry that Sales changed after Admin loaded it.
alter table public."payments" add column if not exists "required_payment_id" bigint references public."applicant_required_payments" ("id") on delete set null;
alter table public."payments" add column if not exists "revision" integer not null default 1;
create index if not exists "payments_required_payment_idx" on public."payments" ("required_payment_id");
create unique index if not exists "payments_one_live_entry_per_required"
  on public."payments" ("required_payment_id") where "required_payment_id" is not null and "status" in ('pending', 'verified');

-- 4. New entries carry no amount.
alter table public."payments" alter column "amount" drop not null;
alter table public."applicant_payments" alter column "amount" drop not null;

-- 5. Deprecated billing columns: kept with their data, no longer read, written or exposed by the API.
comment on column public."payments"."amount" is 'DEPRECATED: billing removed. Not read, written or exposed; NULL for new entries.';
comment on column public."applicant_payments"."amount" is 'DEPRECATED: billing removed. Not read, written or exposed; NULL for new entries.';
comment on column public."applicants"."package_name" is 'DEPRECATED: billing removed (see applicant_payment_plans.basis_note).';
comment on column public."applicants"."total_required_amount" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicants"."total_required_original_amount" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicants"."total_required_discount_percent" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicants"."initial_payment_amount" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicants"."other_fees" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicants"."payments_fully_paid_on" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."package_name" is 'DEPRECATED: billing removed (see basis_note).';
comment on column public."applicant_payment_plans"."agreed_amount_source" is 'DEPRECATED: billing removed (see basis_note).';
comment on column public."applicant_payment_plans"."total_required_amount" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."total_required_original_amount" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."total_required_discount_percent" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."initial_payment_amount" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."other_fees" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."payment_terms" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."promo_name" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."installment_frequency" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."installment_custom_days" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on column public."applicant_payment_plans"."first_due_date" is 'DEPRECATED: billing removed. Not read, written or exposed.';
comment on table public."payment_requests" is 'DEPRECATED: Sales Reports (advanced payment features) are permanently disabled.';
